import { test, expect } from '@playwright/test';

test.describe('File Upload Functionality', () => {
  test('should upload a small text file and confirm upload', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.fill('#file-upload', 'small_text_file.txt');
    await page.click('#file-submit');
    await expect(page).toHaveURL(/.*uploaded/);
    await expect(page.locator('#uploaded-files')).toBeVisible();
    await expect(page.locator('#uploaded-files')).toHaveText('small_text_file.txt');
  });

  test('should not upload an empty file and confirm no upload', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/upload');
    await page.click('#file-submit');
    await expect(page).toHaveURL(/.*uploaded/);
    await expect(page.locator('#uploaded-files')).toBeVisible();
    await expect(page.locator('#uploaded-files')).toHaveText('');
  });
});
